/**
 * OFF-04.8: the ONLY exception to "a package never changes its body at the same version".
 *
 * The OFF-04.7 QA pilot (synthetic data, release 67eaf040) issued signed packages whose definitions were
 * generated by the pilot, not read from the published form. A phone that kept them has, for the SAME
 * form_version, a different content_sha256 than the real package the server issues now, so the strict
 * progression rule rejected every renewal. This module recognises exactly those known pilot packages and
 * allows ONE direction only: known synthetic pilot package -> real package.
 *
 * It is NOT a general rule. Provenance is not taken from the free-text `note`: the OLD package must
 * (1) already be verified by the caller (Ed25519 signature under the pinned key, subject user, device,
 * signed scope snapshot, SHA-256 integrity of the whole definition) and (2) carry a content_sha256 that
 * equals one of the TEN pinned hashes below, i.e. the hash of the complete canonical definition the pilot
 * generated for that exact form/version. Any edit of the definition (including the note) changes that
 * hash and breaks the signature, so a manipulated package cannot reach this path.
 */
import type {QualityPayload} from "./offline-quality-verify.ts";

/** Pilot machine: the OFF-04.7 pilot only ever granted MP1. */
export const SYNTHETIC_PILOT_MACHINE = "MP1";
/** Secondary check only (never sufficient on its own). */
export const SYNTHETIC_PILOT_NOTE = "Synthetic QA-only definition; no industrial captures.";
/** form -> {version, sha256 of the canonical pilot definition, source_definition_checksum of the published form}. */
export const SYNTHETIC_PILOT_PACKAGES: Readonly<Record<string,Readonly<{version:number;content:string;source:string}>>> = {
  "VINTO-P1-18":{version:2,content:"ccb13360c2bda8eb921203995df3410889757f5da53fb388a75dcc6e9f832459",source:"ee6e52d610567db5939a26f6463f52422369d167738e4bd8a36756e03658d812"},
  "VINTO-P1-19":{version:1,content:"1e8d9afa64fe19fa259ed3a8ecdbb6232d0810beffda172b77fca37b241231e9",source:"682908dee7878ce55313011a9a62ef9c0b82dbae404ed129bacaf2366c8a22ff"},
  "VINTO-P1-20":{version:1,content:"29443d5c6472a606aeba52b28c5a3cb6e8c0212f98025215595e5dde16ca1106",source:"1145b41c568e4616dddbfb9f2c5eff21e253a3840df36a87fa416871e30fbbe0"},
  "VINTO-P1-21":{version:2,content:"9a8249cdd04689645a9e9926b58746d40b2eec9a61b69c007abb478cdda847da",source:"669442f12af07d2523feb721bba1b9c0f3604c288a5780326ffaff6b8f6d22ee"},
  "VINTO-P1-22":{version:2,content:"8d8ff2a34d0a99d2fdc56b8d8f568719a81677f5e79855f98eaa2782d27b9ab5",source:"9766e58595263f2723a0143b24e85281565d05e525429e23e4f09b0b3f68c907"},
  "VINTO-P1-24":{version:5,content:"b502a9424b9e9bfaaad6d9ca33f0784c09ca89eb047efc5abb3ffa954c87002d",source:"15b9e1f16b441b03189501dd41ff7e930e01dce0f2a993aa38847ade4ed76191"},
  "VINTO-P1-25":{version:4,content:"c658b14a86448dcbc2fe729d3cf9675ddb31e2718a34b9f7a1e55d781f20bde6",source:"98931956d1017506e5c90c7c9963a42316e3e5673dcafc6b3cb1938bfeb57e12"},
  "VINTO-P1-26":{version:3,content:"7cf56c77fcc433a0af70234e52f8f3bd170eb865b32a3c880301b4c8c0632ed1",source:"9b44be24b7b2948069e189a28ad5a763fc3cfa40c59000e7d04d9f35c8e4d213"},
  "VINTO-P1-27":{version:2,content:"a90d21722e2e5d77853f2ac99b529ff0d31014106779f5d0cb3ac6141957f5df",source:"a4c1b49dbf0ff8758f678fc6773fbe47ee8b9663f075c35e6376958dbe165235"},
  "VINTO-P1-28":{version:1,content:"afc86c68cb81fdd5c24260441dca8bcccccd4a620898670117bb2f1875ab870d",source:"671ba8452d1c04123a2fc0b3eb7341f16df9f656caae53668064e3f774cdcbcb"},
};
const KNOWN_SYNTHETIC_CONTENT=new Set(Object.values(SYNTHETIC_PILOT_PACKAGES).map(p=>p.content));

/** True only for a pilot-synthetic OLD package and a real NEW package of the same form/machine/version/source. Never the reverse. */
export function isSyntheticPilotToRealTransition(old:QualityPayload,next:QualityPayload):boolean{
  const known=SYNTHETIC_PILOT_PACKAGES[old.form_code];
  if(!known)return false;
  // same slot: machine (pilot machine only), form, version; nothing lower, nothing higher
  if(old.machine_code!==SYNTHETIC_PILOT_MACHINE||next.machine_code!==old.machine_code||
     next.form_code!==old.form_code||old.form_version!==known.version||next.form_version!==old.form_version)return false;
  // OLD is exactly a known pilot package (pinned hash of the whole signed definition) from the pilot's own published form
  if(old.content_sha256!==known.content||old.definition.source_definition_checksum!==known.source||
     old.definition.note!==SYNTHETIC_PILOT_NOTE)return false;
  // NEW is a different, non-pilot body of the SAME published definition
  if(next.definition.source_definition_checksum!==old.definition.source_definition_checksum)return false;
  if(next.content_sha256===old.content_sha256||KNOWN_SYNTHETIC_CONTENT.has(next.content_sha256)||
     next.definition.note===SYNTHETIC_PILOT_NOTE)return false;
  // same user/device/protocol; never a capture-enabled package; issued not earlier than the old one
  if(next.subject_user_id.toLowerCase()!==old.subject_user_id.toLowerCase()||next.device_key.toLowerCase()!==old.device_key.toLowerCase())return false;
  if(next.schema!==old.schema||next.issuer!==old.issuer||next.audience!==old.audience||next.kind!==old.kind)return false;
  if(old.captures_enabled!==false||next.captures_enabled!==false)return false;
  const a=Date.parse(old.issued_at),b=Date.parse(next.issued_at);
  return Number.isFinite(a)&&Number.isFinite(b)&&b>=a;
}
